import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/collaborate/version-history-panel.png",s="/docs/images/collaborate/version-history-preview.png",u=JSON.parse('{"title":"Use version history","description":"Look back at earlier versions of a document, name the current one, and restore an older version.","frontmatter":{"title":"Use version history","description":"Look back at earlier versions of a document, name the current one, and restore an older version.","type":"how-to"},"headers":[],"relativePath":"collaborate/version-history.md","filePath":"collaborate/version-history.md"}'),i={name:"collaborate/version-history.md"};function l(h,e,d,c,v,p){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="use-version-history" tabindex="-1">Use version history <a class="header-anchor" href="#use-version-history" aria-label="Permalink to &quot;Use version history&quot;">​</a></h1><p>Every sheet, doc, presentation, note, and board keeps a history of earlier versions that you can preview and restore.</p><p>Wafflebase saves versions automatically as people edit, so a busy afternoon adds several and a quiet week adds none. Restoring is reversible.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need to be signed in and open the document from your workspace. Share links have no history.</li><li>PDFs, images, and other uploaded files have no version history.</li><li>Presentations have no history on a phone. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</li></ul></div><h2 id="open-version-history" tabindex="-1">Open version history <a class="header-anchor" href="#open-version-history" aria-label="Permalink to &quot;Open version history&quot;">​</a></h2><ol><li>Open the document.</li><li>Click the clock icon (<strong>Show version history</strong>) in the header.</li></ol><p>The <strong>Version history</strong> panel opens on the right. Versions are grouped by day, newest first. Most are named <strong>Automatic</strong>. Versions that people named, and <strong>Before restore</strong> versions, show <strong>By you</strong> when you created them. Click the icon again to close the panel.</p><p><img src="'+n+'" alt="Version history panel with two named versions, each with Preview and Restore buttons"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap <strong>⋮</strong> (<strong>More</strong>) in the header, then <strong>Version history</strong>.</p><h2 id="name-the-current-version" tabindex="-1">Name the current version <a class="header-anchor" href="#name-the-current-version" aria-label="Permalink to &quot;Name the current version&quot;">​</a></h2><ol><li>Open version history.</li><li>Type a name in <strong>Name current version</strong>, for example <code>Sent to finance</code>.</li><li>Click <strong>Save</strong>.</li></ol><p>The named version appears at the top of the list. You can&#39;t rename or delete a version later, so name a state before you move on from it.</p><h2 id="preview-a-version" tabindex="-1">Preview a version <a class="header-anchor" href="#preview-a-version" aria-label="Permalink to &quot;Preview a version&quot;">​</a></h2><ol><li>Open version history.</li><li>Click <strong>Preview</strong> on a version.</li></ol><p>The version opens read-only over the document, with a banner that says <em>Viewing &lt;version&gt; from &lt;time&gt;</em>. Nothing changes while you look, and the toolbar and editing shortcuts are turned off. Click another version&#39;s <strong>Preview</strong> to switch, or click <strong>Back to current version</strong> to leave.</p><p>What a preview shows:</p><table tabindex="0"><thead><tr><th>Document</th><th>In a preview</th></tr></thead><tbody><tr><td>Sheet</td><td>The first tab only, without charts and images</td></tr><tr><td>Doc</td><td>The whole document, read-only</td></tr><tr><td>Presentation</td><td>One slide at a time; use <strong>‹</strong> and <strong>›</strong> in the banner to move</td></tr><tr><td>Note</td><td>The rendered Markdown</td></tr><tr><td>Board</td><td>The whole board, fitted to the screen, without pan or zoom</td></tr></tbody></table><h2 id="restore-a-version" tabindex="-1">Restore a version <a class="header-anchor" href="#restore-a-version" aria-label="Permalink to &quot;Restore a version&quot;">​</a></h2><ol><li>Open version history.</li><li>Click <strong>Restore</strong> on the version you want.</li><li>In <strong>Restore this version?</strong>, click <strong>Restore this version</strong>.</li></ol><p>The whole document goes back to that version, including every tab or slide. Before it restores, Wafflebase saves the current state as <strong>Before restore</strong>. To undo a restore, restore <strong>Before restore</strong>; <code>⌘+Z</code> / <code>Ctrl+Z</code> can&#39;t undo it.</p><div class="warning custom-block"><p class="custom-block-title">Comments go back too</p><p>Comments added after the version you restore are removed. Restore <strong>Before restore</strong> to get them back.</p></div><h3 id="restore-from-a-preview" tabindex="-1">Restore from a preview <a class="header-anchor" href="#restore-from-a-preview" aria-label="Permalink to &quot;Restore from a preview&quot;">​</a></h3><p>In a preview, click <strong>Restore this version</strong> in the banner. This restores right away, without the confirmation dialog.</p><p><img src="'+s+'" alt="Doc preview with the Viewing banner, Back to current version, and Restore this version"></p><h2 id="load-older-versions" tabindex="-1">Load older versions <a class="header-anchor" href="#load-older-versions" aria-label="Permalink to &quot;Load older versions&quot;">​</a></h2><p>The panel loads 50 versions at a time. Scroll to the bottom of the list and click <strong>Load older versions</strong> to see more.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Only one restore can run at a time. While one is running, <strong>Restore</strong> is unavailable and says <em>A restore is already in progress</em>.</li><li>Automatic versions don&#39;t show who made the changes.</li><li>Versions can&#39;t be renamed or deleted.</li><li>People on a share link can&#39;t see or restore versions.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/edit-together.html">Edit together</a> to see who changed what as it happens.</li><li><a href="/docs/collaborate/comments.html">Comments and mentions</a> to discuss a change before you restore.</li><li><a href="/docs/collaborate/trash.html">Trash</a> to bring back a deleted document.</li></ul>',31)])])}const g=o(i,[["render",l]]);export{u as __pageData,g as default};
